import React, { useState } from "react";
import { Box, Typography, Grid, Card, CardContent, Button } from "@mui/material";

const positions = [
  {
    title: "Position 1",
    candidates: [
      { id: "1a", name: "Candidate 1a", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "1b", name: "Candidate 1b", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "1c", name: "Candidate 1c", image: "https://via.placeholder.com/120", manifestoLink: "#" },
    ],
  },
  {
    title: "Position 2",
    candidates: [
      { id: "2a", name: "Candidate 2a", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "2b", name: "Candidate 2b", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "2c", name: "Candidate 2c", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "2d", name: "Candidate 2d", image: "https://via.placeholder.com/120", manifestoLink: "#" },
    ],
  },
  {
    title: "Position 3",
    candidates: [
      { id: "3a", name: "Candidate 3a", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "3b", name: "Candidate 3b", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "3c", name: "Candidate 3c", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "3d", name: "Candidate 3d", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "3e", name: "Candidate 3e", image: "https://via.placeholder.com/120", manifestoLink: "#" },
    ],
  },
  {
    title: "Position 4",
    candidates: [
      { id: "4a", name: "Candidate 4a", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "4b", name: "Candidate 4b", image: "https://via.placeholder.com/120", manifestoLink: "#" },
      { id: "4c", name: "Candidate 4c", image: "https://via.placeholder.com/120", manifestoLink: "#" },
    ],
  },
];

const VotingPage = () => {
  const [selectedVotes, setSelectedVotes] = useState({});

  const handleVote = (position, candidateId) => {
    setSelectedVotes((prev) => ({ ...prev, [position]: candidateId }));
  };

  const handleConfirmVote = () => {
    console.log("Votes submitted:", selectedVotes);
    alert("Your votes have been submitted successfully!");
  };

  return (
    <Box sx={{ textAlign: "center", p: 4 }}>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Cast Your Vote
      </Typography>

      {positions.map((position) => (
        <Box key={position.title} sx={{ mb: 5 }}>
          <Typography variant="h5" fontWeight="bold" sx={{ mb: 3 }}>
            {position.title}
          </Typography>

          <Grid container spacing={4} justifyContent="center">
            {position.candidates.map((candidate) => (
              <Grid item key={candidate.id}>
                <Card sx={{ 
                  width: 220,  // Increased width
                  height: 280, // Increased height
                  textAlign: "center", 
                  p: 2, 
                  borderRadius: "16px", // More rounded corners
                  boxShadow: 4,
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between"
                }}>
                  <img 
                    src={candidate.image} 
                    alt={candidate.name} 
                    width="140" 
                    height="140" 
                    style={{ borderRadius: "12px" }} 
                  />
                  <CardContent sx={{ flexGrow: 1, display: "flex", flexDirection: "column" }}>
                    <Typography variant="body1" fontWeight="bold" sx={{ mb: 1 }}>
                      {candidate.name}
                    </Typography>
                    <Box sx={{ mt: "auto" }}> 
                      <Button 
                        variant="contained" 
                        size="small" 
                        sx={{
                          bgcolor: selectedVotes[position.title] === candidate.id ? "blue" : "grey",
                          color: "white",
                          borderRadius: "8px",
                          width: "100%",
                          "&:hover": { bgcolor: selectedVotes[position.title] === candidate.id ? "blue" : "darkgrey" }
                        }}
                        onClick={() => handleVote(position.title, candidate.id)}
                      >
                        CAST VOTE
                      </Button>
                      <Button 
                        variant="outlined" 
                        size="small" 
                        href={candidate.manifestoLink} 
                        target="_blank" 
                        sx={{ 
                          mt: 1, 
                          borderRadius: "8px", 
                          width: "100%" 
                        }}
                      >
                        MANIFESTO
                      </Button>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Box>
      ))}

      <Button 
        variant="contained" 
        onClick={handleConfirmVote} 
        sx={{ 
          mt: 4, 
          bgcolor: "#28a745", // Green color from Login.js
          color: "white", 
          width: "280px", // Slightly bigger confirm button
          height: "60px", 
          fontSize: "18px",
          borderRadius: "10px",
          "&:hover": { bgcolor: "#218838" }
        }}
      >
        CONFIRM VOTE
      </Button>
    </Box>
  );
};

export default VotingPage;
